INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Government-wide statement activity categories
(2, 'Governmental Accounting Fundamentals', 'In the government-wide financial statements under GASB 34, activities are separated into which two categories?', '["Governmental activities and business-type activities", "Operating activities and investing activities", "Current activities and long-term activities", "General fund activities and fiduciary activities"]'::jsonb, 0, 'Under GASB 34, paragraph 12, government-wide financial statements separate all activities into governmental activities (supported by taxes and grants) and business-type activities (financed by fees charged to external users). Fiduciary activities are excluded entirely. Choice D is incorrect because fiduciary activities are not reported in the government-wide statements, and the general fund is a fund-level concept, not a government-wide classification.', 'easy', 1),

-- Q2: medium / L3 — Statement of Activities: program revenue vs general revenue net expense
(2, 'Governmental Accounting Fundamentals', 'Clearwater County''s Parks Department reports $3.2 million in operating expenses. It collects $800,000 in program revenues from park entry fees and state operating grants, and receives $2.4 million from property tax allocations. In the government-wide Statement of Activities, analyze the effect of these revenue classifications on the Parks Department''s net expense presentation.', '["Net expense of $3.2 million with no offset from any revenue source", "Net expense of $0 because all revenue sources fully cover expenses", "Property taxes are assigned to whichever department has the largest deficit", "Net expense of $2.4 million, offset only by program revenues, with property taxes reported as general revenues"]'::jsonb, 3, 'Under GASB 34, paragraphs 37-40, the Statement of Activities presents expenses by function offset only by program revenues (charges for services, operating and capital grants). Clearwater''s $3.2M expense minus $800K program revenue yields a $2.4M net expense funded by general revenues such as property taxes. Choice A is incorrect because program revenues do directly offset departmental expenses — only general revenues like property taxes are excluded from the net expense calculation.', 'medium', 3),

-- Q3: easy / L1 — Encumbrance recording timing in budgetary accounting
(2, 'Governmental Accounting Fundamentals', 'In governmental budgetary accounting, at what point is an encumbrance recorded?', '["When a purchase order is issued, reserving a portion of budgetary authority", "When goods are delivered and the invoice is received", "When the vendor''s payment check is mailed", "When the annual operating budget is formally adopted"]'::jsonb, 0, 'Under GASB standards (Codification Section 1700), encumbrances are recorded when purchase orders or contracts are issued, reserving a portion of the appropriation to ensure budgetary authority is not overspent. The encumbrance is later reversed when goods are received and the actual expenditure is recorded. Choice B is incorrect because goods delivery triggers the expenditure entry and the reversal of the encumbrance, not the initial encumbrance recording.', 'easy', 1),

-- Q4: medium / L2 — Derived tax revenue recognition timing (sales tax)
(2, 'Governmental Accounting Fundamentals', 'Summerfield Township imposes a 1% local sales tax. December 2025 retail sales total $46 million, but merchants do not remit the $460,000 in sales tax to the township until January 25, 2026. The township''s fiscal year ends December 31, 2025. Under GASB 33, when should the general fund recognize the $460,000 in sales tax revenue?', '["In fiscal year 2026, when cash is received from merchants", "In fiscal year 2025, because the underlying sales occurred in December 2025 and the amount is collectible within 60 days", "Split equally between fiscal years 2025 and 2026", "In fiscal year 2025 as a receivable with no corresponding revenue"]'::jsonb, 1, 'Under GASB 33, derived tax revenues such as sales taxes are recognized when the underlying exchange transaction occurs, provided the revenue is measurable and available. The $460,000 relates to December 2025 sales, and since it is collected within 60 days of year-end (January 25, 2026), it meets the availability criterion for modified accrual. Choice A is incorrect because derived tax revenue recognition is tied to the date of the underlying sale, not the date of cash receipt from merchants.', 'medium', 2),

-- Q5: medium / L2 — Expenditure recognition for compensated absences
(2, 'Governmental Accounting Fundamentals', 'Riverside City''s general fund owes employees $920,000 in accumulated vacation pay as of December 31, 2025. Of this amount, $185,000 is expected to be liquidated with currently available resources in the next fiscal year. Under modified accrual, determine the compensated absence expenditure the general fund should recognize.', '["$920,000, the full accumulated obligation", "$735,000, the long-term portion only", "$185,000, the currently payable portion", "$0, deferred until employees use leave"]'::jsonb, 2, 'Under GASB standards and modified accrual accounting, compensated absences are recognized as governmental fund expenditures only to the extent they will be liquidated with current available resources. Of Riverside''s $920,000 total obligation, only $185,000 meets this criterion. The remaining $735,000 is reported as a long-term liability in the government-wide statements only. Choice A is incorrect because governmental funds do not report the full long-term compensated absence liability.', 'medium', 2),

-- Q6: hard / L4 — GASB 68 pension: evaluate experience loss treatment
(2, 'Governmental Accounting Fundamentals', 'Elk Ridge County participates in a cost-sharing defined benefit pension plan. The county''s proportionate share of the total pension liability is $48 million, and plan fiduciary net position is $31 million. Investment returns fell 8% below projections, creating a $3.8 million experience loss. The finance director is deciding how to report this shortfall. Under GASB 68, evaluate the most appropriate treatment of the investment experience loss.', '["Recognize the $3.8 million loss immediately in pension expense", "Report as a deferred outflow of resources and amortize over a five-year closed period", "Reduce plan fiduciary net position and increase the net pension liability by $3.8 million immediately", "Defer recognition until the next actuarial valuation confirms the shortfall persists"]'::jsonb, 1, 'Under GASB 68, paragraphs 33-36, differences between projected and actual earnings on plan investments are reported as deferred outflows (losses) or deferred inflows (gains) and amortized into pension expense over a closed five-year period. This smoothing approach prevents short-term market volatility from distorting pension expense. Choice A is incorrect because GASB 68 specifically prohibits immediate recognition of investment experience differences — the five-year amortization is mandatory.', 'hard', 4),

-- Q7: medium / L2 — Infrastructure assets: modified approach reporting
(2, 'Governmental Accounting Fundamentals', 'Oakwood County maintains 340 miles of roads valued at $125 million. The county uses an asset management system with condition assessments every three years and maintains roads at or above a target rating of B+. Annual preservation spending is $4.2 million. Under GASB 34, determine the reporting treatment for these infrastructure assets.', '["Capitalize the $4.2 million as additions to infrastructure asset value", "Report no expense because infrastructure assets are exempt from depreciation", "Depreciate the $125 million over the estimated useful life of the road network", "Report the $4.2 million in preservation costs as expense under the modified approach"]'::jsonb, 3, 'Under GASB 34, paragraphs 23-25, governments may use the modified approach for eligible infrastructure assets if they maintain an asset management system with periodic condition assessments and demonstrate assets are preserved at or above an established condition level. Preservation costs are expensed rather than depreciated under this approach. Choice C is incorrect because Oakwood meets all modified approach criteria, making depreciation of these infrastructure assets unnecessary.', 'medium', 2),

-- Q8: medium / L3 — Capital outlay: fund vs government-wide treatment
(2, 'Governmental Accounting Fundamentals', 'Briarfield Township purchases a $750,000 fire truck using general fund resources on March 1, 2026. The truck has a 15-year useful life with no salvage value. Analyze how this purchase is reported differently in the governmental fund statements versus the government-wide statements for fiscal year 2026.', '["Fund statements: $750,000 expenditure; Government-wide: $750,000 capitalized asset with $41,667 depreciation expense", "Fund statements: $750,000 capital asset; Government-wide: $750,000 expenditure", "Fund statements: $41,667 depreciation expense; Government-wide: $750,000 expenditure", "Fund statements: $750,000 expenditure; Government-wide: $750,000 expenditure with no capitalization"]'::jsonb, 0, 'Under GASB 34, governmental funds use the current financial resources measurement focus, so capital outlays are reported as expenditures ($750,000). In the government-wide statements using full accrual, the truck is capitalized and depreciated: $750,000 / 15 years x 10/12 months = $41,667 for the partial year. This difference is a key reconciling item. Choice D is incorrect because government-wide statements require capitalization of assets rather than expensing them.', 'medium', 3),

-- Q9: medium / L3 — GASB 75 OPEB: unfunded plan net liability
(2, 'Governmental Accounting Fundamentals', 'Maplewood School District provides retiree health insurance but has not established a trust to fund the obligation. The actuary calculates a total OPEB liability of $14.3 million. The finance director asks how the unfunded plan appears on the government-wide Statement of Net Position. Analyze the reporting effect under GASB 75.', '["The district reports a deferred outflow of $14.3 million instead of a liability", "Net OPEB liability is $0 because unfunded plans require note disclosure only", "Net OPEB liability is reduced by expected future employer contributions to zero", "Net OPEB liability equals $14.3 million because no plan assets exist to offset the total obligation"]'::jsonb, 3, 'Under GASB 75, the net OPEB liability equals the total OPEB liability minus plan fiduciary net position. Because Maplewood has no trust (unfunded plan), plan assets are zero, so the full $14.3 million total OPEB liability is reported as the net OPEB liability on the government-wide Statement of Net Position. Choice B is incorrect because GASB 75 requires recognition of the liability regardless of funding status — note disclosure alone is insufficient.', 'medium', 3),

-- Q10: easy / L1 — MD&A as required supplementary information
(2, 'Governmental Accounting Fundamentals', 'Under GASB 34, which component is presented as required supplementary information before the basic financial statements?', '["The statistical section", "The notes to the financial statements", "Management''s Discussion and Analysis", "The combining fund statements"]'::jsonb, 2, 'Under GASB 34, paragraph 8, Management''s Discussion and Analysis (MD&A) is required supplementary information presented before the basic financial statements. It provides an analytical narrative overview of the government''s financial activities and significant changes from the prior year. Choice A is incorrect because the statistical section is supplementary information presented after the basic financial statements, not before them as required supplementary information.', 'easy', 1),

-- Q11: medium / L3 — Debt service fund: expenditure recognition at maturity
(2, 'Governmental Accounting Fundamentals', 'Hawthorne County issued $20 million in general obligation bonds five years ago. On January 15, 2026, a $2 million principal installment and $600,000 in interest become due and are paid from the debt service fund. An additional $150,000 in interest accrues but does not mature until July 15, 2026. Analyze the expenditure recognition in the debt service fund for January 15.', '["$2,600,000 — only principal and interest due on the maturity date are recognized as expenditures", "$2,750,000 — principal plus all matured and accrued interest", "$2,000,000 — only principal qualifies as a debt service expenditure", "$600,000 — only interest qualifies as a debt service expenditure"]'::jsonb, 0, 'Under GASB 34 and modified accrual accounting, principal and interest on long-term debt are recognized as governmental fund expenditures when due at maturity. The $2M principal and $600K interest due January 15 total $2,600,000 in expenditures. The $150,000 unmatured interest is recognized only in the government-wide statements under full accrual. Choice B is incorrect because the $150,000 has not yet reached its maturity date and does not qualify for governmental fund expenditure recognition.', 'medium', 3),

-- Q12: medium / L2 — Net investment in capital assets calculation
(2, 'Governmental Accounting Fundamentals', 'Prescott City reports gross capital assets of $92 million, accumulated depreciation of $17 million, and outstanding bonds of $21 million used to acquire those assets. There are no unspent bond proceeds. In the government-wide Statement of Net Position, determine the net investment in capital assets.', '["$92 million", "$75 million", "$71 million", "$54 million"]'::jsonb, 3, 'Under GASB 34, net investment in capital assets equals capital assets net of accumulated depreciation ($92M - $17M = $75M) minus outstanding debt related to those assets ($21M), yielding $54 million. This component shows how much of the government''s capital asset base is owned free of debt. Choice B ($75M) is incorrect because it represents net book value without subtracting the related outstanding debt that financed those assets.', 'medium', 2),

-- Q13: hard / L4 — Evaluate depreciation vs modified approach for infrastructure
(2, 'Governmental Accounting Fundamentals', 'Cedarbrook City Council is deciding between the depreciation approach and the modified approach for its $200 million highway network. The city has a condition assessment system rating roads 1-10 with a target of level 6+. The most recent assessment shows 78% of roads at level 6+, down from 85% two years ago. Annual depreciation would be $8 million, while actual preservation spending is $5.5 million. Evaluate which reporting approach is more appropriate.', '["Depreciation approach, because the declining condition level suggests the city cannot sustain the modified approach requirements", "Modified approach, because having a condition assessment system is the sole GASB 34 requirement", "Modified approach, because lower preservation spending produces more favorable expense reporting", "Depreciation approach, because the $200 million valuation exceeds the modified approach threshold"]'::jsonb, 0, 'Under GASB 34, paragraphs 23-25, the modified approach requires the government to demonstrate that infrastructure assets are maintained at or above an established condition level. With only 78% of roads meeting the level 6 target (declining from 85%), Cedarbrook may be unable to assert that condition is maintained, making the depreciation approach more appropriate. Choice B is incorrect because having a condition assessment system alone is insufficient — the government must also demonstrate assets are actually preserved at or above the target level.', 'hard', 4),

-- Q14: medium / L3 — Deferred outflows/inflows in net position calculation
(2, 'Governmental Accounting Fundamentals', 'Ridgeland County''s government-wide Statement of Net Position reports total assets of $145 million, deferred outflows of resources of $8.2 million, total liabilities of $97 million, and deferred inflows of resources of $12.5 million. Analyze how deferred outflows and deferred inflows affect the net position calculation.', '["Both deferred outflows and inflows reduce net position, yielding $27.3 million", "Deferred outflows increase and deferred inflows decrease net position, yielding $43.7 million", "Deferred items are excluded from net position and disclosed in notes only", "Deferred outflows and inflows are netted against liabilities, yielding $43.7 million"]'::jsonb, 1, 'Under GASB 63, net position equals assets plus deferred outflows of resources minus liabilities minus deferred inflows of resources: $145M + $8.2M - $97M - $12.5M = $43.7M. Deferred outflows function like assets (increasing net position), while deferred inflows function like liabilities (decreasing it). Choice A is incorrect because deferred outflows increase rather than decrease net position — they represent consumption of resources applicable to future periods.', 'medium', 3),

-- Q15: easy / L1 — OPEB discount rate for unfunded plans under GASB 75
(2, 'Governmental Accounting Fundamentals', 'Under GASB 75, what discount rate should a government use to measure its OPEB liability when no trust has been established?', '["The expected long-term rate of return on plan investments", "The federal funds rate set by the Federal Reserve", "The government''s own incremental borrowing rate", "A yield or index rate for high-quality municipal bonds"]'::jsonb, 3, 'Under GASB 75, when an OPEB plan has no trust assets (unfunded plan), the discount rate must be based on a yield or index rate for 20-year, tax-exempt general obligation municipal bonds rated AA/Aa or higher. The expected investment return rate cannot be used because there are no plan investments. Choice A is incorrect because the expected rate of return on plan investments only applies when a trust holds sufficient projected assets to cover benefit payments.', 'easy', 1),

-- Q16: medium / L2 — Imposed nonexchange revenue: property tax levied for future year
(2, 'Governmental Accounting Fundamentals', 'Thornbury Township levies $8.4 million in property taxes on October 1, 2025, for the fiscal year beginning January 1, 2026. The township''s fiscal year ends December 31, 2025. Under GASB 33, determine the property tax revenue the general fund should recognize for fiscal year 2025.', '["$8.4 million, because the levy was enacted during 2025", "$4.2 million, representing a prorated portion of the annual levy", "$0, because the taxes are levied for fiscal year 2026 and must be deferred", "$8.4 million less an allowance for estimated uncollectible amounts"]'::jsonb, 2, 'Under GASB 33, paragraph 16, imposed nonexchange revenues such as property taxes are recognized in the period for which they are levied, not when the levy is enacted. Since Thornbury''s levy applies to fiscal year 2026, no revenue is recognized in 2025 — the amount received is reported as a deferred inflow of resources. Choice A is incorrect because the enactment date (October 2025) does not determine the recognition period; the fiscal year to which the levy applies (2026) controls timing.', 'medium', 2),

-- Q17: easy / L1 — Debt service fund purpose
(2, 'Governmental Accounting Fundamentals', 'What is the primary purpose of a debt service fund in governmental accounting?', '["To issue new long-term bonds for capital construction", "To account for principal and interest payments on long-term general government debt", "To track all outstanding liabilities across all government funds", "To manage short-term cash flow borrowings for daily operations"]'::jsonb, 1, 'Under GASB standards, debt service funds are governmental funds used to account for and report financial resources restricted, committed, or assigned to the payment of principal and interest on long-term general government debt. They focus on debt repayment, not debt issuance. Choice A is incorrect because issuing bonds for capital construction is the function of capital projects funds, not debt service funds.', 'easy', 1),

-- Q18: medium / L2 — GASB 68 pension expense components
(2, 'Governmental Accounting Fundamentals', 'Glendale City participates in a single-employer defined benefit pension plan. For fiscal year 2025, the actuary reports service cost of $2.1 million, interest on total pension liability of $3.4 million, projected earnings on plan assets of $2.8 million, and amortization of deferred outflows of $450,000. Under GASB 68, determine pension expense for 2025.', '["$5,500,000", "$2,700,000", "$3,150,000", "$5,950,000"]'::jsonb, 2, 'Under GASB 68, paragraph 32, pension expense includes service cost ($2.1M) plus interest on total pension liability ($3.4M) minus projected earnings on plan assets ($2.8M) plus amortization of deferred outflows ($450K), totaling $3,150,000. Projected earnings reduce pension expense because they represent expected asset growth offsetting the obligation. Choice A ($5.5M) is incorrect because it omits the deduction for projected earnings on plan assets.', 'medium', 2),

-- Q19: hard / L3 — Government-mandated nonexchange: eligibility requirements timing
(2, 'Governmental Accounting Fundamentals', 'Ashford County receives $2.5 million from a state grant for after-school youth programs. The grant agreement specifies three eligibility requirements: (1) the county must appropriate a 20% local match, (2) allowable expenditures may only occur between July 1, 2025 and June 30, 2026, and (3) the county must submit quarterly compliance reports. As of June 30, 2025, the county has appropriated matching funds and received the $2.5 million, but the allowable expenditure period has not begun. Analyze the revenue recognition for fiscal year ending June 30, 2025.', '["Recognize $2.5 million because the cash has been received and matching funds appropriated", "Recognize $2 million and defer $500,000 for the local match requirement", "Recognize $2.5 million as an other financing source rather than revenue", "Recognize $0 — report $2.5 million as a deferred inflow because the time requirement is unmet"]'::jsonb, 3, 'Under GASB 33, paragraphs 18-22, government-mandated and voluntary nonexchange transactions are recognized as revenue when all eligibility requirements are met, including time requirements. The grant specifies that expenditures may only occur between July 1, 2025 and June 30, 2026 — a time requirement not yet met at the June 30, 2025 fiscal year-end. The $2.5 million is reported as a deferred inflow. Choice A is incorrect because receiving cash does not trigger revenue recognition when eligibility requirements, particularly time restrictions, remain unmet.', 'hard', 3),

-- Q20: hard / L4 — Evaluate pension discount rate methodology under GASB 68
(2, 'Governmental Accounting Fundamentals', 'Willowbrook City''s pension plan has fiduciary net position of $280 million against a total pension liability of $410 million. The long-term expected rate of return on investments is 7.25%, but the actuary projects plan assets will be insufficient to cover benefit payments starting in year 22. The high-quality municipal bond index rate is 3.85%. The finance director questions whether a single discount rate is appropriate. Under GASB 68, evaluate the correct discount rate methodology.', '["Use a single blended rate applying 7.25% to benefits payable from plan assets and 3.85% to benefits payable after projected asset depletion", "Use 7.25% for all periods because the plan currently has positive fiduciary net position", "Use 3.85% for all periods because projected depletion makes the higher rate unsupportable", "Use the arithmetic average of 7.25% and 3.85% (5.55%) as a simplified blended rate"]'::jsonb, 0, 'Under GASB 68, paragraph 26, the discount rate is a single blended rate determined by applying the long-term expected return (7.25%) to projected benefits payable from plan assets and the municipal bond index rate (3.85%) to benefits projected after asset depletion. This crossover methodology ensures the rate reflects realistic funding projections. Choice B is incorrect because a current positive net position does not justify using the investment return rate for all periods — the projected depletion in year 22 requires the blended approach.', 'hard', 4),

-- Q21: hard / L4 — Evaluate dual-perspective reporting adequacy
(2, 'Governmental Accounting Fundamentals', 'Sterling County''s citizens raise concerns about declining road quality despite the county spending 95% of its highway fund appropriation. The governmental fund statements show full budgetary compliance, while the government-wide statements reveal $12 million in deferred maintenance and infrastructure condition ratings below target. The county manager argues fiscal accountability is satisfied. Evaluate whether dual-perspective reporting provides adequate accountability.', '["Governmental fund statements are sufficient because 95% budget execution demonstrates responsible stewardship of resources", "Government-wide statements reveal operational deficiencies that budgetary compliance alone does not capture, demonstrating the necessity of dual-perspective reporting", "The government-wide statements overstate the problem because deferred maintenance is not recognized as a GASB liability", "The dual-perspective model is redundant because both statement sets ultimately report the same underlying transactions"]'::jsonb, 1, 'Under GASB Concepts Statement No. 1 and GASB 34, dual-perspective reporting serves two distinct objectives: fiscal accountability (budget compliance) and operational accountability (service delivery effectiveness). Sterling''s fund statements confirm fiscal compliance, but the government-wide statements reveal $12M in deferred maintenance and declining conditions — operational failures invisible in fund-level reporting. Choice A is incorrect because fiscal accountability alone cannot assess whether resources were used effectively to maintain infrastructure.', 'hard', 4),

-- Q22: easy / L2 — General fund as catch-all: identifying which transaction belongs
(2, 'Governmental Accounting Fundamentals', 'Meadowbrook Township collects $2.3 million in property taxes for general operations, receives a $150,000 state grant restricted to firefighter training (deposited in a special revenue fund), issues $500,000 in bonds for a new library (deposited in a capital projects fund), and makes a $180,000 bond principal payment from the debt service fund. Which transaction is recorded in the general fund?', '["The $2.3 million property tax collection for general operations", "The $150,000 restricted firefighter training grant", "The $500,000 bond issuance for the library project", "The $180,000 bond principal payment"]'::jsonb, 0, 'Under GASB standards, the general fund accounts for all financial resources not required to be reported in another fund. Property tax collections for general operations belong in the general fund because they are unrestricted general-purpose resources. Choice B is incorrect because the restricted firefighter training grant is reported in a special revenue fund, as it represents resources restricted to a specific purpose other than debt service or capital projects.', 'easy', 2),

-- Q23: easy / L1 — Custodial fund purpose under GASB 84
(2, 'Governmental Accounting Fundamentals', 'Under GASB 84, what is the purpose of a custodial fund?', '["To account for employee pension benefits held in trust", "To account for resources where the government controls investment decisions", "To account for resources held temporarily in a custodial capacity for outside parties", "To account for resources restricted for capital asset acquisition"]'::jsonb, 2, 'Under GASB 84, custodial funds are fiduciary funds used to report resources held by a government in a purely custodial capacity for individuals, organizations, or other governments. The government collects and distributes these resources but does not own or control them for its own purposes. Choice A is incorrect because employee pension benefits are accounted for in pension trust funds, not custodial funds.', 'easy', 1),

-- Q24: easy / L1 — Private-purpose trust fund identification
(2, 'Governmental Accounting Fundamentals', 'Which type of fiduciary fund accounts for resources held in trust where both principal and income benefit individuals or private organizations outside the government?', '["Custodial fund", "Private-purpose trust fund", "Investment trust fund", "Pension trust fund"]'::jsonb, 1, 'Under GASB 84, private-purpose trust funds report resources held in formal trust arrangements that benefit individuals, private organizations, or other governments — not the reporting government''s own programs. Unlike pension trusts (employee benefits) or investment trusts (external investment pools), private-purpose trusts serve parties entirely outside government operations. Choice A is incorrect because custodial funds hold resources temporarily without a formal trust arrangement, while private-purpose trusts involve binding trust agreements.', 'easy', 1),

-- Q25: hard / L4 — Fund-to-government-wide reconciliation: evaluate adjustments
(2, 'Governmental Accounting Fundamentals', 'Brookhaven City''s governmental funds report total fund balances of $24 million. The finance team identifies reconciling items: (1) capital assets net of depreciation, $62 million; (2) outstanding general long-term debt, $38 million; (3) accrued bond interest of $1.2 million not recorded in governmental funds; and (4) internal service fund net position of $4.5 million predominantly serving governmental departments. A junior accountant argues item 4 should be excluded because internal service funds are proprietary. Evaluate the junior accountant''s position and determine governmental activities net position.', '["$48.0 million — the junior accountant is correct that item 4 should be excluded", "$52.5 million — all items are included except the accrued interest", "$51.3 million — all four items are reconciling adjustments and the junior accountant is incorrect", "$47.3 million — exclude item 4 and add the accrued interest as an asset"]'::jsonb, 2, 'Under GASB 34, paragraph 15, internal service fund net position is consolidated with governmental activities when the predominant customers are governmental departments. The junior accountant is incorrect. The reconciliation is: $24M + $62M - $38M - $1.2M + $4.5M = $51.3M. All four items are valid adjustments from fund balance to net position. Choice A ($48M) is incorrect because excluding the internal service fund violates GASB 34''s requirement to consolidate internal service activities with governmental activities.', 'hard', 4),

-- Q26: medium / L3 — Internal service fund: government-wide reporting treatment
(2, 'Governmental Accounting Fundamentals', 'Westfield County operates a water utility as an enterprise fund and a central printing shop as an internal service fund serving government departments. The audit team at Morrison & Partners observes that the enterprise fund appears in the business-type activities column but the internal service fund does not. Analyze the government-wide reporting treatment of the internal service fund.', '["Internal service fund activities are excluded from government-wide statements like fiduciary funds", "Internal service fund activities are consolidated with governmental activities because the predominant customers are government departments", "Internal service fund activities appear in a third column labeled internal activities", "Internal service fund activities are reported in business-type activities alongside the enterprise fund"]'::jsonb, 1, 'Under GASB 34, paragraph 15, internal service fund activities are typically consolidated with governmental activities in the government-wide statements because their predominant customers are the government''s own departments. Enterprise funds, serving external customers, are reported in business-type activities. Choice D is incorrect because grouping internal service funds with business-type activities would overstate external service delivery and create double-counting of costs already reported as governmental expenditures.', 'medium', 3),

-- Q27: medium / L2 — GASB 68: employer contributions after measurement date
(2, 'Governmental Accounting Fundamentals', 'Pine Valley County''s pension plan has a measurement date of June 30, 2025. Between the measurement date and the fiscal year-end of December 31, 2025, the county contributes $1.8 million to the plan. Under GASB 68, determine the reporting treatment of this post-measurement-date contribution on the December 31 Statement of Net Position.', '["Report as a reduction of the net pension liability on the measurement date", "Report as a deferred outflow of resources, recognized in the following year''s pension expense", "Report as pension expense in the current fiscal year", "Report as a prepaid pension asset in the current financial statements"]'::jsonb, 1, 'Under GASB 68, paragraph 57, employer contributions made after the measurement date but before the fiscal year-end are reported as deferred outflows of resources on the government-wide Statement of Net Position. These contributions are recognized in pension expense in the subsequent fiscal year when the next measurement period begins. Choice C is incorrect because contributions after the measurement date cannot be included in the current year''s pension expense — they must be deferred to align with the actuarial measurement.', 'medium', 2),

-- Q28: medium / L3 — Program revenues vs general revenues in Statement of Activities
(2, 'Governmental Accounting Fundamentals', 'Greenfield City''s Police Department incurs $8.6 million in expenses. It collects $1.1 million in fines and fees (charges for services), receives a $400,000 federal operating grant for community policing, and the city allocates $7.1 million in property tax revenue to cover the remaining cost. Analyze how the Statement of Activities distinguishes program revenues from general revenues for this department.', '["All $8.6 million in funding sources are classified as program revenues that offset the department''s expense", "Property taxes are classified as program revenue because they are allocated to a specific department", "Fines, fees, and the federal grant ($1.5 million) are program revenues; property taxes ($7.1 million) are general revenues that do not offset the department''s net expense directly", "Only the federal grant qualifies as program revenue because fines and fees are exchange transactions"]'::jsonb, 2, 'Under GASB 34, paragraphs 37-40, program revenues include charges for services ($1.1M) and operating/capital grants ($400K), totaling $1.5M. These directly reduce the Police Department''s net expense to $7.1M. Property taxes are general revenues that fund remaining net expenses across all functions. Choice B is incorrect because property taxes are always classified as general revenues regardless of internal budget allocation — they are not program revenues even when earmarked to a department.', 'medium', 3),

-- Q29: medium / L2 — Budgetary comparison schedule: required columns
(2, 'Governmental Accounting Fundamentals', 'Harborview City''s general fund originally budgeted $15.2 million in revenues and $14.8 million in appropriations. A mid-year amendment increased appropriations to $15.1 million. Actual revenues total $15.4 million and expenditures total $14.9 million. Under GASB 34, determine which budget columns must appear in the required budgetary comparison schedule.', '["Both the original budget and the final amended budget, compared with actual results", "Final budget only, since amendments supersede the original", "Actual results only, with budget amounts disclosed in the notes", "Original budget only, to show legislative intent before amendments"]'::jsonb, 0, 'Under GASB 34, paragraph 130, the budgetary comparison schedule must present the original budget, the final amended budget, and actual results for the general fund and major special revenue funds. Both budget columns are required so users can evaluate the significance of amendments and compare actuals against both original plan and final authorization. Choice B is incorrect because omitting the original budget prevents users from assessing whether mid-year amendments reflect sound fiscal management.', 'medium', 2),

-- Q30: easy / L1 — OPEB definition under GASB 75
(2, 'Governmental Accounting Fundamentals', 'Under GASB 75, what does the acronym OPEB represent in governmental accounting?', '["Operating personnel expense budget", "Outstanding pension and employee bonuses", "Obligated postretirement equity benefits", "Other postemployment benefits"]'::jsonb, 3, 'Under GASB 75, OPEB stands for other postemployment benefits, which primarily includes retiree health insurance and other non-pension benefits provided to former employees after separation from active service. GASB 75 requires governments to report net OPEB liabilities on the government-wide Statement of Net Position. Choice A is incorrect because OPEB is not related to operating budgets — it specifically addresses postemployment benefit obligations distinct from pensions.', 'easy', 1)
;

COMMIT;
